import sys, io, csv
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")
sys.path.insert(0, r"C:\Projects\NSCM\_artifacts\_diagnostics")
from ora import conn_info
import oracledb
u,p,d = conn_info()
con = oracledb.connect(user=u,password=p,dsn=d); cur=con.cursor()
cur.execute("ALTER SESSION SET CURRENT_SCHEMA=SCM_MGR")
cur.execute("ALTER SESSION SET NLS_DATE_FORMAT='YYYY-MM-DD HH24:MI:SS'")
def show(title, sql, **b):
    try:
        cur.execute(sql, b); cols=[c[0] for c in cur.description]; rows=cur.fetchall()
    except Exception as e:
        print(f"\n## {title} ERROR {e}"); return
    print(f"\n## {title} ({len(rows)} rows)"); print(" | ".join(cols))
    for r in rows: print(" | ".join("" if v is None else str(v).replace("\n","\n")[:160] for v in r))
show("SCMP_APP sys privs", "SELECT PRIVILEGE FROM DBA_SYS_PRIVS WHERE GRANTEE='SCMP_APP' ORDER BY 1")
show("SCMP_APP roles", "SELECT GRANTED_ROLE FROM DBA_ROLE_PRIVS WHERE GRANTEE='SCMP_APP'")
show("role sys privs", "SELECT GRANTEE, PRIVILEGE FROM DBA_SYS_PRIVS WHERE GRANTEE IN (SELECT GRANTED_ROLE FROM DBA_ROLE_PRIVS WHERE GRANTEE='SCMP_APP') ORDER BY 1,2")
show("EXECUTE grants on PKG_SCP% sample", "SELECT TABLE_NAME, GRANTEE, PRIVILEGE FROM DBA_TAB_PRIVS WHERE OWNER='SCM_MGR' AND TABLE_NAME LIKE 'PKG_SCP0%' AND PRIVILEGE='EXECUTE' ORDER BY 1 FETCH FIRST 15 ROWS ONLY")
show("count PKG with EXECUTE grant", "SELECT COUNT(DISTINCT TABLE_NAME) FROM DBA_TAB_PRIVS WHERE OWNER='SCM_MGR' AND TABLE_NAME LIKE 'PKG_%' AND PRIVILEGE='EXECUTE'")
show("PKG count", "SELECT COUNT(*) FROM DBA_OBJECTS WHERE OWNER='SCM_MGR' AND OBJECT_TYPE='PACKAGE' AND OBJECT_NAME LIKE 'PKG_%'")
show("SHEET_COLUMNS logical key dup", "SELECT PROGRAM_ID,SHEET_NAME,COLUMN_NAME,NVL(DIVISION_ID,'~') D, COUNT(*) FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SCP0100' GROUP BY PROGRAM_ID,SHEET_NAME,COLUMN_NAME,NVL(DIVISION_ID,'~') HAVING COUNT(*)>1")
show("SHEET_COLUMNS constraints", "SELECT CONSTRAINT_NAME, CONSTRAINT_TYPE FROM ALL_CONSTRAINTS WHERE OWNER='SCM_MGR' AND TABLE_NAME='SCM_MST_SHEET_COLUMNS' AND CONSTRAINT_TYPE IN ('P','U')")
show("SHEET_COLUMNS indexes", "SELECT I.INDEX_NAME, I.UNIQUENESS, LISTAGG(C.COLUMN_NAME,',') WITHIN GROUP (ORDER BY C.COLUMN_POSITION) COLS FROM ALL_INDEXES I JOIN ALL_IND_COLUMNS C ON C.INDEX_OWNER=I.OWNER AND C.INDEX_NAME=I.INDEX_NAME WHERE I.OWNER='SCM_MGR' AND I.TABLE_NAME='SCM_MST_SHEET_COLUMNS' GROUP BY I.INDEX_NAME, I.UNIQUENESS")
show("MSG_M constraints/indexes", "SELECT I.INDEX_NAME, I.UNIQUENESS, LISTAGG(C.COLUMN_NAME,',') WITHIN GROUP (ORDER BY C.COLUMN_POSITION) COLS FROM ALL_INDEXES I JOIN ALL_IND_COLUMNS C ON C.INDEX_OWNER=I.OWNER AND C.INDEX_NAME=I.INDEX_NAME WHERE I.OWNER='SCM_MGR' AND I.TABLE_NAME='SCM_ADM_MSG_M' GROUP BY I.INDEX_NAME, I.UNIQUENESS")
show("MSG_M dup check", "SELECT MSG_ID, LANG_CD, COUNT(*) FROM SCM_ADM_MSG_M WHERE MSG_ID IN ('LBL01163','LBL01167') GROUP BY MSG_ID, LANG_CD HAVING COUNT(*)>1")
show("MSG_M max LBL", "SELECT MAX(MSG_ID) FROM SCM_ADM_MSG_M WHERE MSG_ID LIKE 'LBL_____' AND REGEXP_LIKE(MSG_ID,'^LBL[0-9]{5}$')")
show("PLAN_TYPE rows full", "SELECT * FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SCP0100' AND COLUMN_NAME='PLAN_TYPE'")
show("DIVISION_ID null check all SCP0100", "SELECT COUNT(*) TOTAL, SUM(CASE WHEN DIVISION_ID IS NULL THEN 1 ELSE 0 END) NULLDIV FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SCP0100'")
